/* Shared engine types. FullGameState is private/local; never an online view. */
export type Action = "reset" | "ghost" | "under" | "skip" | "burn" | "dump";
export type Card = {
  id: number;
  kind: "number" | "action";
  rank?: number;
  action?: Action;
};
export type Move = {
  type: "play" | "take" | "slam" | "followup";
  source?: "hand" | "up" | "down";
  ids?: number[];
  target?: number;
  index?: number; // wire-only blind slot for the online server
};
/** Local engine moves never use a wire-only blind index. */
export type LocalMove = Omit<Move, "index">;
export type WireMove = Move;
export type Event = {
  type: string;
  seat: number;
  reason?: string;
  action?: string;
  source?: "hand" | "up" | "down";
  count?: number;
  takenCount?: number;
  burnedCount?: number;
  drawnCount?: number;
  bridgeCount?: number;
  target?: number;
  burned?: boolean;
  erodedCount?: number;
  rank?: number;
  move?: number;
};
export type Player = {
  seat: number; hand: Card[]; up: Card[]; down: Card[];
  out: boolean; pickups: number;
};
export type Game = {
  version: string;
  seed: number;
  starterSeat?: number;
  starterReason?: "draw" | "winner" | "practice";
  phase: "setup" | "play" | "over";
  endgameRule?: "classic" | "final-duel";
  omitSkip?: boolean;
  turn: number;
  moves: number;
  stock: Card[];
  pile: Card[];
  ashes: Card[];
  people: Player[];
  limit: null | { type: "under" | "min"; value?: number };
  pendingDump?: null | { seat: number };
  followUp?: null | { seat: number };
  finishedOrder: number[];
  loser: number | null;
  events: Event[];
  blindReveal?: { seat: number; card: Omit<Card,"id">; move: number; expiresAt: number };
  setupReady?: boolean[];
};
export type FullGameState = Game & { rng: number; slamOpen: boolean; startedAt?: number };
export type EngineOptions = { now?: () => number };
export type CreateOptions = { seed?: number; players?: number; endgameRule?: "classic" | "final-duel"; omitSkip?: boolean };
export type EngineApi = {
  VERSION: string;
  create(input?: CreateOptions): FullGameState;
  createEngine(options?: EngineOptions): EngineApi;
  serialize(game: FullGameState): string;
  restore(snapshot: string): FullGameState;
  SNAPSHOT_VERSION: number;
  DECK_SIZE: number;
  ACTIONS: Record<Action, number>;
  deck(version?: string): Card[];
  effectiveDeck(game: Game): Card[];
  count(game: Game): number;
  isLegal(game: Game, card: Card): boolean;
  finalDuelActive(game: Game): boolean;
  finalHandBridge(game: Game, seat: number): null | {hand: Card[]; up: Card[]; kind: Card["kind"]; rank?: number; action?: Action};
  next(game: Game, seat: number): number;
  autoSetup(game: Game, seat: number): Game;
  start(game: Game): Game;
  swap(game: Game, seat: number, handId: number, upId: number): Game;
  invariant(game: Game): boolean;
  options(game: Game, seat: number): Move[];
  slamOptions(game: Game, seat: number): Move[];
  followUpOptions(game: Game, seat: number): Move[];
  stage(game: Game, seat: number): "hand" | "up" | "down" | "out";
  move(game: Game, seat: number, choice: Move): Event;
  resolveDump(game: Game, seat: number, target: number): Event;
  dumpTargets(game: Game, seat: number): number[];
  botDumpTarget(game: Game, seat: number): number;
  choose(game: Game, seat: number, style?: "greedy" | "saver" | "random"): Move;
  topRun(game: Game): { rank: number | null; count: number };
  autoSlam(game: Game, style?: "greedy" | "saver" | "random", exclude?: number): Event | null;
};


export const VERSION: EngineApi["VERSION"];
export const DECK_SIZE: EngineApi["DECK_SIZE"];
export const ACTIONS: EngineApi["ACTIONS"];
export const SNAPSHOT_VERSION: EngineApi["SNAPSHOT_VERSION"];
export const create: EngineApi["create"];
export const createEngine: EngineApi["createEngine"];
export const serialize: EngineApi["serialize"];
export const restore: EngineApi["restore"];
export const deck: EngineApi["deck"];
export const effectiveDeck: EngineApi["effectiveDeck"];
export const start: EngineApi["start"];
export const swap: EngineApi["swap"];
export const autoSetup: EngineApi["autoSetup"];
export const stage: EngineApi["stage"];
export const count: EngineApi["count"];
export const invariant: EngineApi["invariant"];
export const options: EngineApi["options"];
export const slamOptions: EngineApi["slamOptions"];
export const followUpOptions: EngineApi["followUpOptions"];
export const finalHandBridge: EngineApi["finalHandBridge"];
export const topRun: EngineApi["topRun"];
export const isLegal: EngineApi["isLegal"];
export const finalDuelActive: EngineApi["finalDuelActive"];
export const move: EngineApi["move"];
export const resolveDump: EngineApi["resolveDump"];
export const dumpTargets: EngineApi["dumpTargets"];
export const botDumpTarget: EngineApi["botDumpTarget"];
export const choose: EngineApi["choose"];
export const autoSlam: EngineApi["autoSlam"];
export const next: EngineApi["next"];
